komponenten-button--interaktiv.snippet:
import { Component } from '@angular/core';
import { ButtonComponent } from '@conciso/design-system-angular';

@Component({
  selector: 'app-demo',
  imports: [ButtonComponent],
  template: `
    @if (variant === 'filled-on-band') {
    <div
        [style.background]="'var(--' + area + (area === 'ki' ? '-800' : '-700') + ')'"
        style="padding:24px;border-radius:var(--r-md)">
        <cds-button
            [label]="label"
            [variant]="variant"
            [area]="area"
            [tone]="tone"
            [size]="size"
            [full]="full"
            [disabled]="disabled" />
    </div>
    } @else {
    <cds-button
        [label]="label"
        [variant]="variant"
        [area]="area"
        [tone]="tone"
        [size]="size"
        [full]="full"
        [disabled]="disabled" />
    }`,
})
export class DemoComponent {
  label = 'Kontakt aufnehmen';
  variant = 'filled';
  area = 'co';
  tone = 'def';
  size = 'md';
  full = false;
  disabled = false;
}

